mapper.select:
SELECT LISTAGG(REPORT_REASON, ', ')
	WITHIN GROUP (ORDER BY REPORT_REASON) AS PENALTY_REASON
FROM (
	SELECT REPORT_REASON,
		DENSE_RANK() OVER (ORDER BY COUNT(*) DESC) AS RNK
	FROM REPORT
	WHERE REPORTED_MEMBER_NO = #{memberNo}
	GROUP BY REPORT_REASON
)
WHERE RNK = 1;

mapper.insert:
		INSERT INTO PENALTY VALUES 
		(SEQ_PENALTY_NO.NEXTVAL, #{penaltyType}, SYSDATE,
		CASE
 			WHEN #{penaltyType} IN ('WARNING', 'PERMANENT') THEN NULL
  			ELSE SYSDATE + #{plusEndDays}
		END,
  		#{penaltyReason}, DEFAULT, #{memberNo}
		)
